import type { ReactElement } from 'react';
import { useFolderBrowser, type FolderBrowserModel } from './useFolderBrowser';
import './styles.css';

export type Folder = { id: string; name: string; children: Folder[] };
export type Props = {
  folders: Folder[];
  onNavigate: (path: string[]) => void;
};

export function Component({ folders, onNavigate }: Props): ReactElement {
  const model: FolderBrowserModel = useFolderBrowser(folders, onNavigate);

  return (
    <div data-testid="panel" className="folder-panel">
      <output aria-label="Current path">{model.currentPath}</output>
      <button type="button" disabled={!model.canGoBack} onClick={model.back}>
        Back
      </button>
      <ul aria-label="Folders">
        {model.children.map((folder: Folder): ReactElement => (
          <li key={folder.id}>
            <button type="button" onClick={(): void => model.enter(folder.id)}>
              {'Enter ' + folder.name}
            </button>
          </li>
        ))}
      </ul>
      {model.children.length === 0 && <p role="status">No folders</p>}
    </div>
  );
}

